/**
 * What an agent is doing, as far as the roster can honestly tell.
 *
 * Not a health check. The roster does not know whether a process is running
 * and must not imply that it does — every case here is a statement about
 * when the room last spoke, or about what it said.
 */

enum class AgentState {
    
    /**
     * Owes the reader an answer. The core said so — `preview.pending`.
     */
    NEEDS_YOU,
    /**
     * Spoke recently enough to count as active.
     */
    ACTIVE,
    /**
     * Nothing lately, but within living memory.
     */
    IDLE,
    /**
     * Silent long enough that its absence is the fact.
     */
    QUIET;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeAgentState: FfiConverterRustBuffer<AgentState> {
    override fun read(buf: ByteBuffer) = try {
        AgentState.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: AgentState) = 4UL

    override fun write(value: AgentState, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * The outcome of the whole fallback chain — what a host switches on.
 */
sealed class CustomEventView {
    
    data class Rendered(
        val `fields`: List<CustomEventField>, 
        /**
         * How the agent reached this, when it said — see
         * [`CustomEventRenderResult::reasoning`].
         *
         * **This is where reasoning persists.** The live channel carries it
         * on to-device messages, which are not room history and are gone the
         * moment the turn ends; a turn card is a real room event, so
         * reasoning that arrives here is still there tomorrow, on every
         * client, in its place in the conversation.
         */
        val `reasoning`: kotlin.String?, 
        /**
         * The payload declared a `schema_version` above what this renderer
         * knows. Rendered anyway, best effort, and flagged.
         */
        val `newerVersion`: kotlin.Boolean, 
        /**
         * Always present on this variant so a host never has to distinguish
         * "no decision" from "this variant has no such field". Only this
         * variant can carry one: the other two mean no renderer produced
         * anything, so nothing could have set a decision.
         */
        val `decision`: CustomEventDecision?) : CustomEventView() {
        companion object
    }
    
    /**
     * No renderer produced anything, but the event carried a plain-text
     * `body` fallback, as Matrix convention asks of a custom event.
     */
    data class FallbackBody(
        val `text`: kotlin.String) : CustomEventView() {
        companion object
    }
    
    /**
     * Nothing usable at all. Never empty — an empty card reads as a
     * rendering fault rather than as an unsupported event.
     */
    data class Placeholder(
        val `text`: kotlin.String) : CustomEventView() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCustomEventView : FfiConverterRustBuffer<CustomEventView>{
    override fun read(buf: ByteBuffer): CustomEventView {
        return when(buf.getInt()) {
            1 -> CustomEventView.Rendered(
                FfiConverterSequenceTypeCustomEventField.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterOptionalTypeCustomEventDecision.read(buf),
                )
            2 -> CustomEventView.FallbackBody(
                FfiConverterString.read(buf),
                )
            3 -> CustomEventView.Placeholder(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CustomEventView) = when(value) {
        is CustomEventView.Rendered -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeCustomEventField.allocationSize(value.`fields`)
                + FfiConverterOptionalString.allocationSize(value.`reasoning`)
                + FfiConverterBoolean.allocationSize(value.`newerVersion`)
                + FfiConverterOptionalTypeCustomEventDecision.allocationSize(value.`decision`)
            )
        }
        is CustomEventView.FallbackBody -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
        is CustomEventView.Placeholder -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
    }

    override fun write(value: CustomEventView, buf: ByteBuffer) {
        when(value) {
            is CustomEventView.Rendered -> {
                buf.putInt(1)
                FfiConverterSequenceTypeCustomEventField.write(value.`fields`, buf)
                FfiConverterOptionalString.write(value.`reasoning`, buf)
                FfiConverterBoolean.write(value.`newerVersion`, buf)
                FfiConverterOptionalTypeCustomEventDecision.write(value.`decision`, buf)
                Unit
            }
            is CustomEventView.FallbackBody -> {
                buf.putInt(2)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is CustomEventView.Placeholder -> {
                buf.putInt(3)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * The render decision for one item.
 */
sealed class ItemView {
    
    /**
     * An ordinary message. `muted` is `m.notice` — automated output from
     * bridges and agents, de-emphasised but never suppressed, since it is
     * the msgtype most of this org's agent traffic actually uses.
     *
     * `blocks` is the parsed body, so a host draws rich text without
     * touching markdown or HTML itself. See `crate::rich`.
     */
    data class Bubble(
        val `muted`: kotlin.Boolean, 
        val `blocks`: List<RichBlock>) : ItemView() {
        companion object
    }
    
    object Emote : ItemView()
    
    
    data class System(
        val `text`: kotlin.String) : ItemView() {
        companion object
    }
    
    /**
     * The line between what has been read and what has not, which the SDK
     * inserts at most once per timeline.
     *
     * Carries no text: the divider says everything, and a label repeated at
     * every scroll position would be chrome pretending to be content.
     */
    object UnreadMarker : ItemView()
    
    
    data class Placeholder(
        val `text`: kotlin.String) : ItemView() {
        companion object
    }
    
    /**
     * An `m.image`. `alt` is never empty — it falls back through the media
     * filename, then the plain body, to a generic label — because this is
     * genuine message content rather than decoration.
     *
     * `width`/`height` are the image's own pixel dimensions, `None` when the
     * sender's client never reported them. A host uses them to reserve the
     * thumbnail's box *before* its bytes are requested, so a lazy list never
     * reflows once they land.
     */
    data class Image(
        val `alt`: kotlin.String, 
        val `width`: kotlin.ULong?, 
        val `height`: kotlin.ULong?) : ItemView() {
        companion object
    }
    
    /**
     * An `m.file`/`m.audio`/`m.video`: an informative row naming what the
     * message is. `label` is precomputed so a host needs no msgtype table.
     */
    data class MediaFile(
        val `label`: MediaFileLabel, 
        val `filename`: kotlin.String, 
        val `size`: kotlin.ULong?, 
        val `mimetype`: kotlin.String?) : ItemView() {
        companion object
    }
    
    /**
     * The line between one day and the next.
     *
     * It carries no text: the date is formatted by the host from the item's
     * own `timestamp_ms`, because formatting reads a clock and a locale and
     * both belong where the rendering is.
     *
     * **This used to have no variant**, and this function carried a note
     * telling every caller to special-case the kind before asking. The
     * desktop did. iOS did not, and put "Unsupported event (dateDivider)" in
     * the middle of a conversation — a contract in a comment is one a second
     * host will eventually miss. As a variant, ignoring it fails to compile.
     */
    object DateDivider : ItemView()
    
    
    /**
     * A suite event — a Kaambaan card or run, a permission request, station
     * status. `view` is the whole fallback-chain decision: a host renders its
     * three states but never makes that decision itself.
     */
    data class CustomEvent(
        val `view`: CustomEventView, 
        /**
         * What to call this card on screen — "Turn", "Permission".
         *
         * A card headed `dev.agentpod.turn.v1` is showing a reader the
         * address of a schema where a name for a thing belongs. The event
         * type is still carried below, for a card whose type nothing here
         * recognises and for anyone diagnosing one.
         */
        val `label`: kotlin.String, 
        /**
         * The Matrix event type as the card's header should show it —
         * truncated from the left, never from the right, and never rendered
         * with a right-to-left base direction. See [`display_event_type`]:
         * this string is sender-controlled, and the obvious CSS approach
         * hands the bidi algorithm a hostile string and lets a crafted type
         * reorder itself on screen.
         */
        val `eventType`: kotlin.String) : ItemView() {
        companion object
    }
    
    object None : ItemView()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeItemView : FfiConverterRustBuffer<ItemView>{
    override fun read(buf: ByteBuffer): ItemView {
        return when(buf.getInt()) {
            1 -> ItemView.Bubble(
                FfiConverterBoolean.read(buf),
                FfiConverterSequenceTypeRichBlock.read(buf),
                )
            2 -> ItemView.Emote
            3 -> ItemView.System(
                FfiConverterString.read(buf),
                )
            4 -> ItemView.UnreadMarker
            5 -> ItemView.Placeholder(
                FfiConverterString.read(buf),
                )
            6 -> ItemView.Image(
                FfiConverterString.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalULong.read(buf),
                )
            7 -> ItemView.MediaFile(
                FfiConverterTypeMediaFileLabel.read(buf),
                FfiConverterString.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            8 -> ItemView.DateDivider
            9 -> ItemView.CustomEvent(
                FfiConverterTypeCustomEventView.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            10 -> ItemView.None
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ItemView) = when(value) {
        is ItemView.Bubble -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
