                + FfiConverterSequenceTypeRichBlock.allocationSize(value.`blocks`)
            )
        }
        is ItemView.Emote -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ItemView.System -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
        is ItemView.UnreadMarker -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ItemView.Placeholder -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
            )
        }
        is ItemView.Image -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`alt`)
                + FfiConverterOptionalULong.allocationSize(value.`width`)
                + FfiConverterOptionalULong.allocationSize(value.`height`)
            )
        }
        is ItemView.MediaFile -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeMediaFileLabel.allocationSize(value.`label`)
                + FfiConverterString.allocationSize(value.`filename`)
                + FfiConverterOptionalULong.allocationSize(value.`size`)
                + FfiConverterOptionalString.allocationSize(value.`mimetype`)
            )
        }
        is ItemView.DateDivider -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ItemView.CustomEvent -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeCustomEventView.allocationSize(value.`view`)
                + FfiConverterString.allocationSize(value.`label`)
                + FfiConverterString.allocationSize(value.`eventType`)
            )
        }
        is ItemView.None -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: ItemView, buf: ByteBuffer) {
        when(value) {
            is ItemView.Bubble -> {
                buf.putInt(1)
                FfiConverterBoolean.write(value.`muted`, buf)
                FfiConverterSequenceTypeRichBlock.write(value.`blocks`, buf)
                Unit
            }
            is ItemView.Emote -> {
                buf.putInt(2)
                Unit
            }
            is ItemView.System -> {
                buf.putInt(3)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is ItemView.UnreadMarker -> {
                buf.putInt(4)
                Unit
            }
            is ItemView.Placeholder -> {
                buf.putInt(5)
                FfiConverterString.write(value.`text`, buf)
                Unit
            }
            is ItemView.Image -> {
                buf.putInt(6)
                FfiConverterString.write(value.`alt`, buf)
                FfiConverterOptionalULong.write(value.`width`, buf)
                FfiConverterOptionalULong.write(value.`height`, buf)
                Unit
            }
            is ItemView.MediaFile -> {
                buf.putInt(7)
                FfiConverterTypeMediaFileLabel.write(value.`label`, buf)
                FfiConverterString.write(value.`filename`, buf)
                FfiConverterOptionalULong.write(value.`size`, buf)
                FfiConverterOptionalString.write(value.`mimetype`, buf)
                Unit
            }
            is ItemView.DateDivider -> {
                buf.putInt(8)
                Unit
            }
            is ItemView.CustomEvent -> {
                buf.putInt(9)
                FfiConverterTypeCustomEventView.write(value.`view`, buf)
                FfiConverterString.write(value.`label`, buf)
                FfiConverterString.write(value.`eventType`, buf)
                Unit
            }
            is ItemView.None -> {
