/**
 * The quoted parent of a reply, as a host sees it.
 */
sealed class ReplyQuoteView {
    
    /**
     * The parent's details never loaded — a real and common outcome, not an
     * edge case. The core already folds Unavailable/Pending/Error together,
     * so this is the one shape a host needs. It renders as "Original message
     * unavailable" rather than an empty quote or a spinner that will never
     * resolve on its own.
     */
    object Unavailable : ReplyQuoteView()
    
    
    /**
     * `excerpt` and `label` are mutually exclusive: `label` is only ever
     * `Some` when `excerpt` is `None`. A ready parent can still have nothing
     * to quote — a redacted, sticker, poll or undecryptable parent has a
     * sender but no body — and `label` is the short classification of why,
     * in the same vocabulary this module's placeholders use.
     */
    data class Available(
        val `sender`: kotlin.String, 
        val `excerpt`: kotlin.String?, 
        val `label`: kotlin.String?) : ReplyQuoteView() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeReplyQuoteView : FfiConverterRustBuffer<ReplyQuoteView>{
    override fun read(buf: ByteBuffer): ReplyQuoteView {
        return when(buf.getInt()) {
            1 -> ReplyQuoteView.Unavailable
            2 -> ReplyQuoteView.Available(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ReplyQuoteView) = when(value) {
        is ReplyQuoteView.Unavailable -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ReplyQuoteView.Available -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`sender`)
                + FfiConverterOptionalString.allocationSize(value.`excerpt`)
                + FfiConverterOptionalString.allocationSize(value.`label`)
            )
        }
    }

    override fun write(value: ReplyQuoteView, buf: ByteBuffer) {
        when(value) {
            is ReplyQuoteView.Unavailable -> {
                buf.putInt(1)
                Unit
            }
            is ReplyQuoteView.Available -> {
                buf.putInt(2)
                FfiConverterString.write(value.`sender`, buf)
                FfiConverterOptionalString.write(value.`excerpt`, buf)
                FfiConverterOptionalString.write(value.`label`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





