/**
 * What the room pane should offer.
 */

enum class RoomAffordance {
    
    /**
     * An ordinary room: write in it.
     */
    COMPOSE,
    /**
     * An invitation: accept or decline.
     */
    RESPOND_TO_INVITATION,
    /**
     * Nothing honest to offer, and inventing an affordance for a state
     * nobody can act on is worse than a quiet pane.
     */
    NOTHING;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeRoomAffordance: FfiConverterRustBuffer<RoomAffordance> {
    override fun read(buf: ByteBuffer) = try {
        RoomAffordance.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: RoomAffordance) = 4UL

    override fun write(value: RoomAffordance, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





