    override fun write(value: List<RichBlock>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeRichBlock.write(it, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceTypeRichInline: FfiConverterRustBuffer<List<RichInline>> {
    override fun read(buf: ByteBuffer): List<RichInline> {
        val len = buf.getInt()
        return List<RichInline>(len) {
            FfiConverterTypeRichInline.read(buf)
        }
    }

    override fun allocationSize(value: List<RichInline>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeRichInline.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<RichInline>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeRichInline.write(it, buf)
        }
    }
}



/**
 * Typealias from the type name used in the UDL file to the builtin type.  This
 * is needed because the UDL type name is used in function/method signatures.
 * It's also what we have an external type that references a custom type.
 */
public typealias CustomPayload = kotlin.String
public typealias FfiConverterTypeCustomPayload = FfiConverterString

